import pandas as pd, numpy as np
from math import isfinite

input_path='/root/environment/data/ckd_lab_data.csv'
raw=pd.read_csv(input_path, dtype=str)

def parse_val(x):
    if x is None: return np.nan
    s=str(x).strip()
    if s=='' or s.lower() in {'na','nan','null','none'}: return np.nan
    s=s.replace(',', '.').replace(' ', '')
    if s.count('.')>1:
        parts=s.split('.')
        s=''.join(parts[:-1]) + '.' + parts[-1]
    try:
        return float(s)
    except Exception:
        return np.nan

num=raw.copy()
for c in num.columns:
    if c=='patient_id':
        num[c]=pd.to_numeric(num[c], errors='coerce')
    else:
        num[c]=num[c].map(parse_val)
num=num.dropna().reset_index(drop=True)

# use latest config (from previous run) but we will inspect for specific columns
ranges={
    'Troponin_I': (0.0, 1.0),
    'Troponin_T': (0.0, 1.0),
    'Total_Bilirubin': (0.1, 25.0),
    'Direct_Bilirubin': (0.0, 10.0),
    'Glucose': (30.0, 800.0),
    'Magnesium': (0.5, 10.0),
}

rules_force={
    'Troponin_I': [(lambda v: v>1.0, lambda v: v/1000.0)],
    'Troponin_T': [(lambda v: v>1.0, lambda v: v/1000.0)],
    'Total_Bilirubin': [(lambda v: v>5.0, lambda v: v/17.1)],
    'Direct_Bilirubin': [(lambda v: v>2.0, lambda v: v/17.1)],
    'Glucose': [],
    'Magnesium': [],
}

rules={
    'Glucose': [(lambda v: v<30.0, lambda v: v*18.0)],
    'Magnesium': [(lambda v: v<1.3, lambda v: v*2.43)],
}


def in_range(v,r):
    return r[0] <= v <= r[1]

for col in ['Troponin_I','Troponin_T','Total_Bilirubin','Direct_Bilirubin','Glucose','Magnesium']:
    r=ranges[col]
    force_rules=rules_force.get(col, [])
    col_rules=rules.get(col, [])
    vals=num[col].copy()
    out_vals=[]
    conv_vals=[]
    for v in vals:
        if v is None or not isfinite(v):
            continue
        v2=v
        for cond, func in force_rules:
            if cond(v2):
                v2=func(v2)
        # keep track of converted
        conv_vals.append(v2)
        if not in_range(v2, r):
            # try non-force conversions
            used=False
            for cond, func in col_rules:
                if cond(v2):
                    cand=func(v2)
                    if in_range(cand, r):
                        used=True
                        v2=cand
                        break
            if not used and not in_range(v2, r):
                out_vals.append(v2)
    if out_vals:
        print(col, 'out_of_range count', len(out_vals), 'min', min(out_vals), 'max', max(out_vals))
    else:
        print(col, 'no out_of_range')
